@Component("employmentContract-handler")
@ProcessingGroup("employmentContract-processing-group")
public class EmploymentContractEventHandler {
	
	// core constructor
	EmploymentContractEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateEmploymentContractEvent
     */
    @EventHandler
    public void handle( CreateEmploymentContractEvent event) {
        entityManager.persist(new EmploymentContract(event.getEmploymentContractId(), event.getContractNumber(), event.getStartDate(), event.getEndDate(), event.getWorkHoursPerWeek(), event.getEmployee(), event.getCompensationPackage(), event.getWorkSchedule(), event.getLocation(), event.getPayrollCalendar(), event.getEmploymentType(), event.getStatus(), event.getPayFrequency()));
    }

    /*
     * @param	event UpdateEmploymentContractEvent
     */
    @EventHandler
    public EmploymentContract handle( UpdateEmploymentContractEvent event) {
    	entityManager.merge(new EmploymentContract(event.getEmploymentContractId(), event.getContractNumber(), event.getStartDate(), event.getEndDate(), event.getWorkHoursPerWeek(), event.getEmployee(), event.getCompensationPackage(), event.getWorkSchedule(), event.getLocation(), event.getPayrollCalendar(), event.getEmploymentType(), event.getStatus(), event.getPayFrequency()));
    }
    
    /*
     * @param	event DeleteEmploymentContractEvent
     */
    @EventHandler
    public void on( DeleteEmploymentContractEvent event) {
    	EmploymentContract entity = new EmploymentContract();
   
    	// ------------------------------------------
    	// apply the EmploymentContractId
    	// ------------------------------------------
    	entity.setEmploymentContractId( event.getEmploymentContractId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final EmploymentContractRepository employmentContractEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(EmploymentContractEventHandler.class.getName());

}
